  assigned_at DateTime @db.Timestamptz

  /// Timestamp when this admin role was revoked, or null if active.
  revoked_at DateTime? @db.Timestamptz

  /// Account status: e.g., 'active', 'revoked', 'suspended'. Policy and
  /// lifecycle management uses this field.
  status String

  /// Timestamp when the admin record was created (for auditability).
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to this admin record.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for lifecycle management.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_posts discussion_board_posts[]
  discussion_board_comments discussion_board_comments[]
  discussion_board_post_reports discussion_board_post_reports[]
  discussion_board_comment_reports discussion_board_comment_reports[]
  discussion_board_user_sanctions discussion_board_user_sanctions[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_rule_logs discussion_board_rule_logs[]
  discussion_board_operation_logs discussion_board_operation_logs[]
  discussion_board_policy_change_logs discussion_board_policy_change_logs[]

  @@unique([email])
  @@index([status])
  @@index([assigned_at])
  @@index([revoked_at])
